import{_ as a,o as t,c as o,a3 as s}from"./chunks/framework.DWzkrVA3.js";const g=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"general/concepts.md","filePath":"general/concepts.md"}'),r={name:"general/concepts.md"};function n(i,e,l,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>A few ideas run through all of Anthology. Knowing them makes the rest of the manual easier to follow.</p><h2 id="recordings-releases-and-tracks" tabindex="-1">Recordings, releases and tracks <a class="header-anchor" href="#recordings-releases-and-tracks" aria-label="Permalink to &quot;Recordings, releases and tracks&quot;">​</a></h2><ul><li>A <strong>recording</strong> is one performance of a piece of music – the audio itself.</li><li>A <strong>release</strong> (album) is a published collection of tracks.</li><li>A <strong>track</strong> is a recording in the context of a release: its number, its disc, and possibly a title or artist that differs on that album.</li></ul><p>The same recording often appears on several releases – the original album, a compilation, a remaster. Anthology keeps <strong>one original file per recording</strong> and lets every release reference it. When you play a track from a compilation, Anthology shows and delivers it with the compilation&#39;s tags and cover.</p><h2 id="managed-and-referenced-originals" tabindex="-1">Managed and referenced originals <a class="header-anchor" href="#managed-and-referenced-originals" aria-label="Permalink to &quot;Managed and referenced originals&quot;">​</a></h2><ul><li><strong>Managed</strong> originals belong to Anthology: they live in the library volume, and Anthology may move them or replace them with a better copy.</li><li><strong>Referenced</strong> originals stay in a folder you own. Anthology reads them and never moves, renames or deletes them; it writes their tags only if you allow it.</li></ul><h2 id="effective-quality" tabindex="-1">Effective quality <a class="header-anchor" href="#effective-quality" aria-label="Permalink to &quot;Effective quality&quot;">​</a></h2><p>The quality a file declares (for example &quot;FLAC, 24 bit&quot;) is not always the quality it has: a lossless file can contain upscaled lossy audio. Anthology analyses the audio and shows the <strong>effective quality</strong> as a badge. It uses the effective quality to rank duplicates, to decide replacements and to choose transcodes – and never upscales.</p><h2 id="jobs" tabindex="-1">Jobs <a class="header-anchor" href="#jobs" aria-label="Permalink to &quot;Jobs&quot;">​</a></h2><p>Long work – imports, identification, quality analysis, bulk edits, downloads – runs as a <strong>job</strong> on the server. Jobs show their progress live, can be paused and continue after a restart.</p><h2 id="the-review-list-and-conflicts" tabindex="-1">The review list and conflicts <a class="header-anchor" href="#the-review-list-and-conflicts" aria-label="Permalink to &quot;The review list and conflicts&quot;">​</a></h2><p>When Anthology is not sure – two recordings that may be the same, a MusicBrainz suggestion, a better copy of a file – it asks in the <strong>review list</strong>. When an automatic source (such as MusicBrainz) would change a value someone set by hand, the change becomes a <strong>conflict</strong> that you accept or reject.</p><h2 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h2><p>Music plays on <strong>this device</strong> (the browser) or on an <strong>output</strong> such as a Raumfeld zone. On an output, the server plays the queue track by track, and your device becomes a remote control.</p>',15)])])}const p=a(r,[["render",n]]);export{g as __pageData,p as default};
